import fs from "node:fs";
import path from "node:path";
import { run } from "../exec.js";
import { paths } from "../paths.js";

export type SfxKind = "whoosh" | "pop";

const SFX_DIR = path.join(paths.root, "assets", "sfx");

/**
 * Synthesized sound effects (generated by FFmpeg, so there is no licence to worry about).
 * Drop your own whoosh.wav / pop.wav into assets/sfx to replace them.
 */
const RECIPES: Record<SfxKind, string[]> = {
  // Band-limited pink noise with a fast swell and a longer tail.
  whoosh: [
    "-f", "lavfi", "-i", "anoisesrc=color=pink:duration=0.7:amplitude=0.9:seed=7",
    "-af", "highpass=f=350,lowpass=f=5500,afade=t=in:st=0:d=0.28:curve=exp,afade=t=out:st=0.28:d=0.42:curve=log,volume=1.6",
  ],
  // A short pitch-dropping blip.
  pop: [
    "-f", "lavfi", "-i", "aevalsrc='0.7*sin(2*PI*(520+780*exp(-28*t))*t)*exp(-22*t)':s=48000:d=0.16",
    "-af", "afade=t=out:st=0.1:d=0.06",
  ],
};

export async function ensureSfx(ff: string): Promise<Record<SfxKind, string>> {
  fs.mkdirSync(SFX_DIR, { recursive: true });
  const out = {} as Record<SfxKind, string>;
  for (const kind of Object.keys(RECIPES) as SfxKind[]) {
    const file = path.join(SFX_DIR, `${kind}.wav`);
    if (!fs.existsSync(file)) {
      const r = await run(ff, ["-hide_banner", "-loglevel", "error", "-y", ...RECIPES[kind], "-ar", "48000", "-ac", "2", file]);
      if (r.code !== 0) throw new Error(`sfx ${kind} failed: ${r.stderr.slice(-200)}`);
    }
    out[kind] = file;
  }
  return out;
}
